// unmarshalBool reads a bool field. Fields are read with the same functions as
// the generated code, so that both return the same errors.
func (f *field) unmarshalBool(r *Reader) (any, error) {
	if !f.repeated {
		var v bool
		if err := r.ReadBool(&v); err != nil {
			return nil, err
		}
		return nonZero(r, v)
	}

	if f.fixedLength == 0 {
		var vs []bool
		if err := r.ReadBools(&vs); err != nil {
			return nil, err
		}
		return packedValue(f, r, vs)
	}

	vs, err := makePacked[bool](r, f.fixedLength, func(b []byte) uint64 {
		return uint64(len(b))
	})
	if err != nil {
		return nil, err
	}
	if err := r.ReadBoolsInto(vs); err != nil {
		return nil, err
	}
	return packedValue(f, r, vs)
}

func (f *field) marshalBool(w Writer, value any) (Writer, error) {
	return marshalPacked(f, w, value, sizeBool, appendBool)
}

func (f *field) unmarshalString(r *Reader) (any, error) {
	return unmarshalUnpacked(
		f,
		r,
		func(msgBytes []byte) (string, bool, error) {
			if !utf8.Valid(msgBytes) {
				return "", false, ErrStringNotUTF8
			}
			if r.Unsafe {
				return unsafeString(msgBytes), len(msgBytes) == 0, nil
			}
			if err := r.UseMemory(uint64(len(msgBytes))); err != nil {
				return "", false, err
			}
			return string(msgBytes), len(msgBytes) == 0, nil
		},
	)
}

func (f *field) marshalString(w Writer, value any) (Writer, error) {
	return marshalUnpacked(
		f,
		w,
		value,
		func(w Writer, value string) (Writer, error) {
			w.AppendBytes(value)
			return w, nil
		},
	)
}

func (f *field) unmarshalBytes(r *Reader) (any, error) {
	if f.pointer && f.repeated {
		return unmarshalUnpacked(f, r, func(msgBytes []byte) (*[]byte, bool, error) {
			if len(msgBytes) == 0 {
				return nil, true, nil
			}
			msgReader := Reader{B: msgBytes}
			if err := msgReader.UnwrapPointer(); err != nil {
				return nil, false, err
			}
			var value *[]byte
			if err := r.MakePointer(&value); err != nil {
				return nil, false, err
			}
			var err error
			*value, err = copyBytes(r, msgReader.B)
			return value, false, err
		})
	}
	return unmarshalUnpacked(
		f,
		r,
		func(msgBytes []byte) ([]byte, bool, error) {
			msgBytes, err := copyBytes(r, msgBytes)
			// Non-nil pointers are not considered empty.
			return msgBytes, len(msgBytes) == 0 && !f.pointer, err
		},
	)
}

func (f *field) marshalBytes(w Writer, value any) (Writer, error) {
	if f.pointer && f.repeated {
		return marshalUnpacked(
			f,
			w,
			value,
			func(w Writer, value *[]byte) (Writer, error) {
				if value == nil {
					w.Append(EmptyBytes)
					return w, nil
				}
				w.AppendUint(SizePointerPresenceTag + SizeBytes(*value))
				w.Append(PointerPresenceTag)
				w.AppendBytes(*value)
				return w, nil
			},
		)
	}
	return marshalUnpacked(
		f,
		w,
		value,
		func(w Writer, value []byte) (Writer, error) {
			w.AppendBytes(value)
			return w, nil
		},
	)
}

func (f *field) unmarshalFixedBytes(r *Reader) (any, error) {
	return unmarshalUnpacked(
		f,
		r,
		func(msgBytes []byte) ([]byte, bool, error) {
			msgBytes, err := copyBytes(r, msgBytes)
			return msgBytes, isBytesEmpty(msgBytes), err
		},
	)
}

func (f *field) unmarshalMessage(r *Reader) (any, error) {
	// [Reader.SubReader] checks the depth limit before reading each entry. The
	// depth limit is the same for every entry, so checking it once before the
	// first entry is equivalent.
	if r.DepthLimit == 0 {
		return nil, ErrDepthLimitExceeded
	}
	// msgReader is declared outside of unmarshal, which captures r, so that it
	// does not escape to the heap.
	var msgReader Reader
	// unmarshal reads a message from msgBytes, charging its memory to r.
	unmarshal := func(msgBytes []byte) (Any, error) {
		msgReader = Reader{
			B:               msgBytes,
			Unsafe:          r.Unsafe,
			MemoryRemaining: r.MemoryRemaining,
			DepthLimit:      r.DepthLimit - 1,
			Context:         r.Context,
		}
		a, err := f.message.unmarshal(&msgReader)
		r.MemoryRemaining = msgReader.MemoryRemaining
		return a, err
	}
	if f.pointer && f.repeated {
		return unmarshalUnpacked(f, r, func(msgBytes []byte) (*Any, bool, error) {
			if len(msgBytes) == 0 {
				return nil, true, nil
			}
			ptrReader := Reader{B: msgBytes}
			if err := ptrReader.UnwrapPointer(); err != nil {
				return nil, false, err
			}
			var a *Any
			if err := r.MakePointer(&a); err != nil {
				return nil, false, err
			}
			var err error
			*a, err = unmarshal(ptrReader.B)
			return a, false, err
		})
	}
	return unmarshalUnpacked(f, r, func(msgBytes []byte) (Any, bool, error) {
		if len(msgBytes) == 0 {
			return Any{}, !f.pointer, nil
		}
		a, err := unmarshal(msgBytes)
		return a, false, err
	})
}

func (f *field) marshalMessage(w Writer, af *AnyField) (Writer, error) {
	if !f.repeated {
		v, ok := af.Value.(Any)
		if !ok {
			return Writer{}, ErrInvalidFieldType
		}
		w.AppendUint(atomic.LoadUint64(&af.cachedSize))
		return f.message.marshal(w, &v)
	}

	if f.pointer {
		vl, ok := af.Value.([]*Any)
		if !ok {
			return Writer{}, ErrInvalidFieldType
		}
		if len(vl) == 0 {
			return Writer{}, ErrInvalidLength
		}

		marshalElement := func(w Writer, v *Any) (Writer, error) {
			if v == nil {
				w.Append(EmptyBytes)
				return w, nil
			}
			innerSize := atomic.LoadUint64(&v.cachedSize)
			w.AppendUint(SizePointerPresenceTag + SizeUint(innerSize) + innerSize)
			w.Append(PointerPresenceTag)
			w.AppendUint(innerSize)
			return f.message.marshal(w, v)
		}

		var err error
		w, err = marshalElement(w, vl[0])
		if err != nil {
			return Writer{}, err
		}

		for _, v := range vl[1:] {
			w.Append(f.tag)
			w, err = marshalElement(w, v)
			if err != nil {
				return Writer{}, err
			}
		}
		return w, nil
	}

	vl, ok := af.Value.([]Any)
	if !ok {
		return Writer{}, ErrInvalidFieldType
	}
	if len(vl) == 0 {
		return Writer{}, ErrInvalidLength
	}

	marshalElement := func(w Writer, v *Any) (Writer, error) {
		innerSize := atomic.LoadUint64(&v.cachedSize)
		w.AppendUint(innerSize)
		return f.message.marshal(w, v)
	}

	var err error
	w, err = marshalElement(w, &vl[0])
	if err != nil {
		return Writer{}, err
	}

	rvl := vl[1:]
	for i := range rvl {
		w.Append(f.tag)
		w, err = marshalElement(w, &rvl[i])
		if err != nil {
			return Writer{}, err
		}
	}
	return w, nil
}

// unmarshalInt reads a zigzag encoded varint field. Fields are read with the
// same functions as the generated code, so that both return the same errors.
func unmarshalInt[T Int](f *field, r *Reader) (any, error) {
	if !f.repeated {
		var v T
		if err := r.ReadInt(&v); err != nil {
			return nil, err
		}
		return nonZero(r, v)
	}

	if f.fixedLength == 0 {
		var vs []T
		if _, err := r.ReadInts(&vs); err != nil {
			return nil, err
		}
		return packedValue(f, r, vs)
	}

	vs, err := makePacked[T](r, f.fixedLength, countInts)
	if err != nil {
		return nil, err
	}
	if _, err := r.ReadIntsInto(vs); err != nil {
		return nil, err
	}
	return packedValue(f, r, vs)
}

