// makePacked allocates the slice to read a packed field into, when the field
// must contain exactly fixedLength values. count returns the number of values
// in the packed bytes.
func makePacked[T any](
	r *Reader,
	fixedLength uint64,
	count func(b []byte) uint64,
) ([]T, error) {
	var (
		peek = Reader{B: r.B, Unsafe: true}
		b    []byte
	)
	if err := peek.ReadBytes(&b); err != nil {
		return nil, err
	}
	// The spec may be malicious, so fixedLength is bounded by the actual number
	// of values in the field. If the field contains fewer than fixedLength
	// values, the slice still exceeds the number of values so that reading the
	// field fails as if we allocated the full fixedLength.
	var vs []T
	err := r.MakeSlice(&vs, min(fixedLength, count(b)+1))
	return vs, err
}

// nonZero returns v, as [box] does, if it is not the zero value.
func nonZero[T comparable](r *Reader, v T) (any, error) {
	if IsZero(&v) {
		return nil, ErrZeroValue
	}
	return box(r, v)
}

// packedValue returns values, as [box] does, if they are a valid packed field.
func packedValue[T comparable](f *field, r *Reader, values []T) (any, error) {
	isZero := true
	for _, value := range values {
		isZero = isZero && IsZero(&value)
	}
	if len(values) == 0 || (f.fixedLength > 0 && isZero) {
		return nil, ErrZeroValue
	}
	return box(r, values)
}

// box returns v as an interface after charging the memory of the boxed copy
// of v against r.
func box[T any](r *Reader, v T) (any, error) {
	if err := r.UseMemory(uint64(unsafe.Sizeof(v))); err != nil {
		return nil, err
	}
	return v, nil
}

func sizeFint32[T Int32](T) uint64 { return SizeFint32 }

func sizeFint64[T Int64](T) uint64 { return SizeFint64 }

func sizeBool(bool) uint64 { return SizeBool }

// The append functions take and return w by value, because passing &w to a
// function value would move w to the heap.

func appendInt[T Int](w Writer, v T) Writer {
	w.AppendInt(v)
	return w
}

func appendUint[T Uint](w Writer, v T) Writer {
	w.AppendUint(v)
	return w
}

func appendFint32[T Int32](w Writer, v T) Writer {
	w.AppendFint32(v)
	return w
}

func appendFint64[T Int64](w Writer, v T) Writer {
	w.AppendFint64(v)
	return w
}

func appendBool(w Writer, v bool) Writer {
	w.AppendBool(v)
	return w
}

func marshalPacked[T comparable](
	f *field,
	w Writer,
	value any,
	size func(T) uint64,
	appendValue func(w Writer, value T) Writer,
) (Writer, error) {
	if !f.repeated {
		// If there is only one entry, write it.
		v, ok := value.(T)
		if !ok {
			return Writer{}, ErrInvalidFieldType
		}
		return appendValue(w, v), nil
	}

	vl, ok := value.([]T)
	if !ok {
		return Writer{}, ErrInvalidFieldType
	}

	var packedSize uint64
	for _, v := range vl {
		packedSize += size(v)
	}
	w.AppendUint(packedSize)
	for _, v := range vl {
		w = appendValue(w, v)
	}
	return w, nil
}

// unmarshalUnpacked reads a length-delimited field. Each entry is read with
// [field.readEntry] and then converted into a value with unmarshal.
//
// r is only passed to direct calls, so that it does not escape to the heap.
func unmarshalUnpacked[T any](
	f *field,
	r *Reader,
	unmarshal func(msgBytes []byte) (T, bool, error),
) (any, error) {
	// Read the first entry manually because the tag is already stripped.
	entry, err := f.readEntry(r)
	if err != nil {
		return nil, err
	}
	if !f.repeated {
		// If there is only one entry, return it.
		value, isZero, err := unmarshal(entry)
		if err != nil {
			return nil, err
		}
		if isZero {
			return nil, ErrZeroValue
		}
		return box(r, value)
	}

	// Count the number of additional entries after the first entry.
	var count, capacity uint64
	if f.fixedLength == 0 {
		countMinus1, err := CountBytes(r.B, f.tag)
		if err != nil {
			return nil, err
		}
		count = countMinus1 + 1
		capacity = count
	} else {
		// The spec is untrusted, so the fixed length is bounded by the number
		// of entries present before it is used to size the allocation. The
		// error is ignored because, if the malformed entry is part of this
		// field, reading the entries below reports it.
		countMinus1, _ := CountBytes(r.B, f.tag)
		count = f.fixedLength
		capacity = min(count, countMinus1+1)
	}
	if err := r.UseSliceMemory[T](capacity); err != nil {
		return nil, err
	}

	value, isZero, err := unmarshal(entry)
	if err != nil {
		return nil, err
	}

	values := make([]T, 1, capacity)
	values[0] = value

	// Read the rest of the entries, stripping the tag each time.
	for range count - 1 {
		if !HasPrefix(r.B, f.tag) {
			return nil, ErrUnknownField
		}
		r.B = r.B[len(f.tag):]

		entry, err := f.readEntry(r)
		if err != nil {
			return nil, err
		}

		value, isFieldZero, err := unmarshal(entry)
		if err != nil {
			return nil, err
		}
		values = append(values, value)
		isZero = isZero && isFieldZero
	}
	if f.fixedLength > 0 && isZero {
		return nil, ErrZeroValue
	}
	return box(r, values)
}

// readEntry reads a length-prefixed entry of f from r without copying it.
func (f *field) readEntry(r *Reader) ([]byte, error) {
	var length uint64
	if err := r.ReadUint(&length); err != nil {
		return nil, err
	}
	if f.kind == FieldTypeFixedBytes && length != f.fixedBytes {
		return nil, ErrInvalidLength
	}
	if length > uint64(len(r.B)) {
		return nil, ErrUnexpectedEOF
	}
	msgBytes := r.B[:length]
	r.B = r.B[length:]
	return msgBytes, nil
}

// copyBytes copies b, charging its memory to r, unless r.Unsafe is set.
func copyBytes(r *Reader, b []byte) ([]byte, error) {
	if r.Unsafe {
		return b, nil
	}
	if err := r.UseMemory(uint64(len(b))); err != nil {
		return nil, err
	}
	return slices.Clone(b), nil
}

func marshalUnpacked[T any](
	f *field,
	w Writer,
	value any,
	marshal func(w Writer, value T) (Writer, error),
) (Writer, error) {
	if !f.repeated {
		// If there is only one entry, write it.
		v, ok := value.(T)
		if !ok {
			return Writer{}, ErrInvalidFieldType
		}
		return marshal(w, v)
	}

	vl, ok := value.([]T)
	if !ok {
		return Writer{}, ErrInvalidFieldType
	}

	if len(vl) == 0 {
		return Writer{}, ErrInvalidLength
	}

	// Write the first entry manually because the tag is already written.
	var err error
	w, err = marshal(w, vl[0])
	if err != nil {
		return Writer{}, err
	}

	for _, v := range vl[1:] {
		w.Append(f.tag)
		w, err = marshal(w, v)
		if err != nil {
			return Writer{}, err
		}
	}
	return w, nil
}

// isBytesEmpty returns true if the byte slice is all zeros.
func isBytesEmpty(b []byte) bool {
	for _, v := range b {
		if v != 0 {
			return false
		}
	}
	return true
}
